<script setup lang="ts">
import { onLoad } from '@dcloudio/uni-app'; import { ref } from 'vue'; import { api } from '../../services/api';
const id=ref('');const item=ref<any>(null);const working=ref(false);
async function load(){try{item.value=await api(`/me/notices/${id.value}`);}catch(e:any){uni.showToast({title:e.message,icon:'none'});}}
async function confirm(){working.value=true;try{await api(`/me/notices/${id.value}/confirm`,'POST',{versionNo:item.value.currentVersionNo});uni.showToast({title:'已确认',icon:'success'});await load();}catch(e:any){uni.showToast({title:e.message,icon:'none'});}finally{working.value=false;}}
onLoad((q)=>{id.value=String(q?.id??'');load();});
</script>
<template><view class="page"><view v-if="!item" class="empty">正在加载…</view><template v-else><view class="card"><view class="meta"><text class="badge">{{item.level}}</text><text class="muted">版本 {{item.currentVersionNo}}</text></view><text class="title">{{item.title}}</text><text class="deadline">截止：{{item.deadlineAt?new Date(item.deadlineAt).toLocaleString():'无'}}</text><view class="divider"/><text class="body">{{item.content}}</text></view><view v-if="item.attachments?.length" class="card"><text class="section-title">附件</text><view v-for="file in item.attachments" :key="file.id" class="attachment"><text>{{file.originalName||file.fileName}}</text><text class="muted">请在网页或小程序中下载查看</text></view></view><button v-if="!item.confirmedAt" class="primary-btn fixed" :loading="working" @tap="confirm">我已阅读并知晓</button><view v-else class="confirmed">✓ 已于 {{new Date(item.confirmedAt).toLocaleString()}} 确认</view></template></view></template>
<style scoped>.meta{display:flex;justify-content:space-between}.badge{padding:8rpx 14rpx;color:#fff;font-size:21rpx;border-radius:10rpx;background:#008da1}.title{display:block;margin:28rpx 0 14rpx;font-size:38rpx;font-weight:800}.deadline{color:#e07a42;font-size:24rpx}.divider{height:1px;margin:28rpx 0;background:#edf1f1}.body{white-space:pre-wrap;line-height:1.8}.attachment{padding:18rpx 0;border-top:1px solid #edf1f1}.attachment text{display:block}.fixed{margin-top:30rpx}.confirmed{padding:25rpx;color:#19866f;text-align:center;border-radius:18rpx;background:#e9f8f3}</style>
